// This file is generated by AI.
//
// (本文件原为"参考音频列表"对话框, 现改为只负责**添加一条**参考音频。)

// 添加参考音频对话框。
//
// 只处理"这一条要加什么": 选文件 → 填参考文本与语言 → 确认。
// 列表本身不在这里展示 —— 它就在「编辑角色」对话框里, 再弹一个同样的列表纯属重复,
// 而且用户还得在两个几乎一样的界面之间来回找。
//
// 音频过长时会接一个裁剪对话框 (展示波形与自动建议区间); 过短则由后端静默补尾。

import { Button, Input } from '@fluentui/react-components';
import { FolderRegular } from '@fluentui/react-icons';
import { open as openDialog } from '@tauri-apps/plugin-dialog';
import { useEffect, useState } from 'react';

import type { Character } from '../commands/voice';
import { voiceAddReference } from '../commands/voice';
import { AppDialog } from '../components/AppDialog';
import { Select, toOptions } from '../components/Select';
import { useAppStore } from '../state/store';
import { voiceController } from './controller';
import { ReferenceTrimDialog } from './ReferenceTrimDialog';
import { LANGUAGE_LABELS } from './types';

interface Props {
  character: Character;
  onClose: () => void;
  onAdded: () => void;
}

export function AddReferenceDialog({ character, onClose, onAdded }: Props) {
  const [source, setSource] = useState('');
  const [text, setText] = useState('');
  const [language, setLanguage] = useState(character.language || 'zh');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [trim, setTrim] = useState<{ start: number; end: number } | null>(null);

  // 换角色时同步语言默认值
  useEffect(() => setLanguage(character.language || 'zh'), [character.id, character.language]);

  const pickFile = async () => {
    setError(null);
    const picked = await openDialog({ multiple: false, filters: [{ name: '音频', extensions: ['wav'] }] });
    if (typeof picked === 'string') setSource(picked);
  };

  /** 确认添加: 过长时先进入裁剪, 否则直接入库 */
  const confirm = async () => {
    if (!source.trim() || !text.trim()) return;
    setBusy(true);
    setError(null);
    try {
      const info = await voiceController.inspectAudio(source);
      if (info.tooLong) {
        const suggestion = await voiceController.trimSuggestion(source);
        setTrim({ start: suggestion.suggested.start, end: suggestion.suggested.end });
        return;
      }
      await add(source, undefined, undefined);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : String(caught));
    } finally {
      setBusy(false);
    }
  };

  const add = async (path: string, start?: number, end?: number) => {
    const updated = await voiceAddReference(character.id, {
      source: path,
      text: text.trim(),
      language,
      tags: [],
      start,
      end,
    });
    voiceController.setCharacters(
      useAppStore.getState().voiceCharacters.map((item) => (item.id === updated.id ? updated : item))
    );
    setTrim(null);
    onAdded();
    onClose();
  };

  const ready = source.trim().length > 0 && text.trim().length > 0 && !busy;

  return (
    <>
      <AppDialog
        title={`添加参考音频 · ${character.name}`}
        description="参考文本必须与音频逐字一致；时长须在 3~10 秒之间。"
        size="medium"
        height={360}
        onClose={onClose}
        footer={
          <>
            <Button appearance="secondary" disabled={busy} onClick={onClose}>
              取消
            </Button>
            <Button appearance="primary" disabled={!ready} onClick={() => void confirm()}>
              {busy ? '处理中…' : '添加'}
            </Button>
          </>
        }
      >
        <div className="reference-add-form">
          <div className="voice-field">
            <span className="voice-label">音频文件</span>
            <div className="workbench-input-row">
              <Input value={source} readOnly placeholder="选择一段 3~10 秒的清晰人声" title={source} />
              <Button
                appearance="secondary"
                icon={<FolderRegular />}
                title="选择音频文件"
                onClick={() => void pickFile()}
              />
            </div>
          </div>

          {/* 语言取值很短, 固定窄宽度, 不参与拉伸 */}
          <label className="voice-field reference-add-language">
            <span className="voice-label">语言</span>
            <Select
              value={language}
              title="参考文本使用的语言"
              options={toOptions(LANGUAGE_LABELS)}
              onChange={setLanguage}
            />
          </label>

          <label className="voice-field">
            <span className="voice-label">
              参考文本
              <span className="voice-required">*</span>
              <span className="voice-label-note">必须与音频逐字一致</span>
            </span>
            <Input
              value={text}
              placeholder="例如：我有什么不对劲的地方吗？"
              onChange={(_, data) => setText(data.value)}
            />
          </label>

          {error && <p className="voice-error">{error}</p>}
        </div>
      </AppDialog>

      {trim && (
        <ReferenceTrimDialog
          path={source}
          suggestedStart={trim.start}
          suggestedEnd={trim.end}
          text={text}
          language={language}
          requireText={false}
          onTextChange={setText}
          onLanguageChange={setLanguage}
          busy={busy}
          error={error}
          onCancel={() => setTrim(null)}
          onConfirm={(start, end) => void add(source, start, end)}
        />
      )}
    </>
  );
}
